<?php namespace App\Repositories\MongoDB; use App\Repositories\Interfaces\SkillRepositoryInterface;
final class MongoSkillRepository extends MongoRepository implements SkillRepositoryInterface { private function c(){return $this->db->db()->skills;} public function all():array{return $this->rows($this->c()->find([],['sort'=>['sort_order'=>1,'name'=>1]]));} public function find(string $id):?array{$x=$this->c()->findOne(['_id'=>$this->id($id)]);return $x?$this->row($x):null;} public function save(array $d,?string $id=null):string{if($id){$this->c()->updateOne(['_id'=>$this->id($id)],['$set'=>$d]);return $id;}return (string)$this->c()->insertOne($d)->getInsertedId();} public function delete(string $id):bool{return $this->c()->deleteOne(['_id'=>$this->id($id)])->getDeletedCount()===1;} public function count():int{return $this->c()->countDocuments();} }
